const slides=[
{title:'The quote is sent. The next step is missing.',text:'A homeowner has a replacement estimate. Two weeks later, the quote is still open. Nobody knows whether they are comparing, waiting, or have a question.',bubble:'“We liked the quote. We just haven’t had time to talk it through.”'},
{title:'Start with eligible estimates.',text:'Read the agreed CRM fields. Exclude sold jobs, clear losses, active conversations, duplicates and opt-outs. Only contact homeowners through an appropriate approved channel.',bubble:'Example record: retail roof replacement · open estimate · follow-up due.'},
{title:'Make the follow-up specific.',text:'The message refers to the estimate the homeowner actually received. Approved information guides the reply. Pricing changes and uncertain answers go to the rep.',bubble:'“Hi Alex, it’s the estimate team at Example Roofing. Is there anything you still want to go through on the roof estimate?”'},
{title:'A reply becomes a useful sales handoff.',text:'The homeowner asks about timing. The system flags the question and creates a handoff for the roofing rep. The rep confirms details and arranges the estimate review.',bubble:'Rep brief: homeowner still considering · timing question · original estimate attached.'},
{title:'Count held conversations. Then measure sales.',text:'Confirm that the review happened. Track any resulting sale separately. Five conversations is a pilot deliverable—not a claim that five roofs will sell.',bubble:'Track: eligible → contacted → replied → review held → won / lost.'},
{title:'Check whether your pipeline fits.',text:'Bring your open-estimate count, average contribution per job, current CRM and current follow-up process. We’ll scope the pilot before any commitment.',bubble:'200 eligible estimates · a named sales rep · agreed messaging and scope.'}];let n=0;const dialog=document.querySelector('#demo');function render(){let s=slides[n];document.querySelector('#slide').innerHTML=`<h2>${s.title}</h2><p>${s.text}</p><div class="demo-bubble">${s.bubble}</div>`;document.querySelector('#progress').textContent=`${n+1} / ${slides.length}`;document.querySelector('#prev').disabled=n===0;document.querySelector('#next').disabled=n===slides.length-1;}document.querySelector('#show-demo').onclick=()=>{n=0;render();dialog.showModal();};document.querySelector('.close').onclick=()=>dialog.close();document.querySelector('#prev').onclick=()=>{n--;render()};document.querySelector('#next').onclick=()=>{n++;render()};dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});document.querySelector('#fitform').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const fit=f.get('crm')==='JobNimbus'&&['200–399','400+'].includes(f.get('volume'));location.href='confirmation.html?fit='+String(fit);};